<?php
defined('BASEPATH') or exit('No direct script access allowed'); class Leadgen_whatsapp extends AdminController { public function __construct() { parent::__construct(); if (staff_cant('view', 'settings') && staff_cant('view', 'leadgen_whatsapp')) { access_denied('Leadgen Whatsapp'); } } public function index() { if ($this->input->post()) { if (staff_cant('edit', 'settings') && staff_cant('edit', 'leadgen_whatsapp')) { access_denied('Leadgen Whatsapp'); } $settings = $this->input->post('settings'); if (is_array($settings)) { foreach ($settings as $key => $value) { update_option($key, $value); }log_activity('Leadgen WhatsApp Settings Updated'); } set_alert('success', _l('settings_updated')); redirect(admin_url('leadgen_whatsapp')); } $data['title'] = _l('leadgen_whatsapp_settings'); $data['lead_statuses'] = $this->db->order_by('statusorder', 'asc')->get(db_prefix() . 'leads_status')->result_array(); $this->load->view('settings', $data); } }
